import {reports as localReports} from './domain.js';
import {vaultProfiles,unlockVault,enableVault,saveVault,vaultUnlocked,lockVault,removeVault} from './offline.js';

const app=document.getElementById('app'),modal=document.getElementById('modal');
let user,csrf,state,site,config={},page='dashboard',query='',statusFilter='',typeFilter='',journal=null,baseState=null,manualOffline=false,lastSnapshotAt=null,menuExpanded=true,profileOpen=false,activeContext='',queue=[],online=navigator.onLine,busy=false,detailTab='overview',selectedOrder=null;
let offlineReady=Promise.resolve(),checkingConnection=false;
const labels={admin:'Administración',supervisor:'Supervisor',technician:'Técnico',operator:'Operador',warehouse:'Bodega',manager:'Jefatura'};
const nav=[['dashboard','Inicio','home',['admin','supervisor','manager']],['orders','Órdenes de trabajo','clipboard',['admin','supervisor','technician','warehouse','manager']],['requests','Avisos de falla','message',['admin','supervisor','operator']],['assets','Activos','factory',Object.keys(labels)],['plans','Preventivos','calendar',['admin','supervisor','technician','manager']],['inventory','Inventario','package',['admin','supervisor','warehouse','technician','manager']],['planning','Planificación','calendar',['admin','supervisor','manager']],['condition','Por condición','chart',['admin','supervisor','technician','manager']],['procedures','Procedimientos','list',['admin','supervisor','technician']],['reports','Reportes','chart',['admin','supervisor','manager']],['resources','Recursos','tool',['admin','supervisor','warehouse','technician']],['notices','Alertas','bell',Object.keys(labels)],['sync','Sincronización','cloud',Object.keys(labels)],['admin','Usuarios y permisos','users',['admin']],['settings','Configuración','settings',Object.keys(labels)]];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={chart:'M3 3v18h18M7 15v-4m5 4V7m5 8v-6',clipboard:'M9 5H5v16h14V5h-4M9 3h6v4H9zM8 12h8m-8 4h5',message:'M21 15a3 3 0 0 1-3 3H8l-5 3V6a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3zM8 8h8m-8 4h5',factory:'M3 21V9l6 3V7l6 3V3h5v18zM7 17h1m4 0h1m4 0h1',calendar:'M3 5h18v16H3zM7 3v4m10-4v4M3 10h18m-14 4h2m4 0h2',package:'m3 7 9-4 9 4v11l-9 4-9-4zM3 7l9 5 9-5m-9 5v10M7 5l9 5',list:'M9 5h12M9 12h12M9 19h12M3 5h1m-1 7h1m-1 7h1',tool:'m14 6 4 4 4-4a7 7 0 0 1-9 9l-8 7-3-3 8-8a7 7 0 0 1 4-9z',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4',cloud:'M7 18a5 5 0 1 1 1-10 7 7 0 0 1 13 3 4 4 0 0 1-1 8M9 17l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',search:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16m6 14 5 5',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18',arrow:'m9 5 7 7-7 7',download:'M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4',logout:'M9 3H3v18h6m3-14 5 5-5 5M8 12h13'};
Object.assign(paths,{
 home:'M3 11 12 3l9 8M5 10v11h14V10M9 21v-7h6v7',
 gear:'m9 2-.7 3-2 .9-2.7-1.4-2 3.5L4 10v3l-2.4 2 2 3.5L6.3 17l2 .9.7 3h4l.7-3 2-.9 2.7 1.5 2-3.5L20 13v-3l2.4-2-2-3.5-2.7 1.4-2-.9L15 2zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',
 motor:'M6 7h12v12H6zM3 10H1v6h2M21 10h2v6h-2M9 4h6V2H9zM12 4v3M8 10h8M8 13h8M8 16h8M8 19v3m8-3v3',
 cubes:'m12 2 5 3-5 3-5-3zM7 5v6l5 3 5-3V5M6 12l5 3-5 3-5-3zM1 15v6l5 3 5-3v-6m6-3 5 3-5 3-5-3zM12 15v6l5 3 5-3v-6',
 users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a7 7 0 0 1 14 0v2M17 5a4 4 0 0 1 0 7m2 3a6 6 0 0 1 3 6',
 user:'M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10M3 22a9 9 0 0 1 18 0',
 database:'M3 5c0-5 18-5 18 0s-18 5-18 0v14c0 5 18 5 18 0V5M3 12c0 5 18 5 18 0',
 refresh:'M21 7v5h-5M3 17v-5h5M5 7a8 8 0 0 1 14-2l2 7M3 12l2 7a8 8 0 0 0 14-2',
 'chevron-down':'m6 9 6 6 6-6','chevron-up':'m6 15 6-6 6 6','arrow-right':'M4 12h16m-6-6 6 6-6 6'
});
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.list}"/></svg>`;
const fmt=(s,time=true)=>s?new Intl.DateTimeFormat('es-CL',{dateStyle:'medium',...(time?{timeStyle:'short'}:{}),timeZone:state?.sites?.find(x=>x.id===site)?.timezone||'America/Santiago'}).format(new Date(s)):'—';
const money=(v,currency='CLP')=>new Intl.NumberFormat('es-CL',{style:'currency',currency}).format(v||0);
const n=v=>new Intl.NumberFormat('es-CL',{maximumFractionDigits:2}).format(v||0);
const name=(kind,id,key='name')=>state?.[kind]?.find(x=>x.id===id)?.[key]||'—';
const currentSite=()=>state?.sites?.find(x=>x.id===site);
const can=(...roles)=>user?.role==='admin'||roles.includes(user?.role);
const closed=o=>['Finalizada','Cancelada'].includes(o.status);
const due=o=>!closed(o)&&Date.parse(o.dueAt)<Date.now();
const badge=s=>`<span class="badge ${['En proceso','Aceptado','Vinculado','Asignada'].includes(s)?'blue':['Finalizada','Operativo','Pass','Revisado','Importado'].includes(s)?'green':['En espera de repuesto','Por revisar','Pendiente','Detenido','Validado'].includes(s)?'amber':['Rechazado','Fail','Cancelada'].includes(s)?'red':''}">${esc(s)}</span>`;
const button=(title,action,id='',primary=false,ico='')=>`<button type="button" ${action?`data-do="${action}"`:''} data-id="${esc(id)}" class="${primary?'primary':''}">${ico?icon(ico):''}${esc(title)}</button>`;
const link=(title,action,id)=>`<button type="button" class="link" data-do="${action}" data-id="${esc(id)}">${esc(title)}</button>`;
const empty=(title,subtitle='Los nuevos registros aparecerán aquí.')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(subtitle)}</div>`;
const heading=(title,subtitle,actions='')=>`<div class="page-heading"><div><h1>${esc(title)}</h1><p class="sub">${esc(subtitle)}</p></div><div class="row">${actions}</div></div>`;
const table=(headers,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('No hay registros');
const stat=(label,value,note='')=>`<div class="stat"><div class="stat-label">${esc(label)}</div><div class="stat-value">${esc(value)}</div><div class="small">${esc(note)}</div></div>`;
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),5500);}
async function api(path,options={}){
 const {timeoutMs=12000,...request}=options;let response;
 try{response=await fetch(path,{...request,headers:{...(request.body?{'Content-Type':'application/json','X-CSRF-Token':csrf||''}:{}),...(user&&path!=='/api/login'?{'X-Workspace-User':user.id}:{}),...request.headers},signal:AbortSignal.timeout(timeoutMs)});}
 catch(cause){online=false;updateConnectionStatus();const error=Error('No se puede conectar con el servidor. Tus cambios locales se conservan; vuelve a conectar para sincronizarlos.',{cause});error.network=true;throw error;}
 let data;try{data=await response.json();}catch(cause){const error=Error('El servidor no confirmó la operación. El registro se conserva para reintentarlo.',{cause});error.network=true;throw error;}
 if(!response.ok){const error=Error(data.error||'No se pudo completar la operación');error.status=response.status;error.details=data.details;if(response.status>=500||response.status===429)error.network=true;throw error;}return data;
}
function updateConnectionStatus(){const label=app.querySelector('#connection-label');if(label)label.textContent='Servidor: '+(online&&!manualOffline?'En línea':'Sin conexión');const dot=app.querySelector('#connection-dot');if(dot)dot.classList.toggle('offline',!online||manualOffline);}
async function checkConnection(){
 if(checkingConnection||manualOffline||!user)return;checkingConnection=true;
 try{await api('/healthz',{timeoutMs:2500});const reconnected=!online;online=true;updateConnectionStatus();if(reconnected&&vaultUnlocked()&&journal)await synchronize();}
 catch{online=false;updateConnectionStatus();}finally{checkingConnection=false;}
}
function journalChanged(j){state=j.state;queue=j.entries;baseState=j.base;if(j.lastError?.network)online=false;}
const persist=async()=>{const data=journal?journal.export():{schemaVersion:2,user,site,state:baseState||state,queue,savedAt:new Date().toISOString()};data.user=user;data.site=site;data.config=config;data.savedAt=new Date().toISOString();return saveVault(data);};
function setupJournal(base,entries=[],local={}){
 journal=new WorkJournal({user,site,base,entries,drafts:local.drafts||{},files:local.files||{},save:async data=>{const saved=await saveVault({...data,config});assertLocal(saved,'Desbloquea la copia de trabajo antes de guardar.');},send:action=>api('/api/actions',{method:'POST',body:JSON.stringify(action)}),receipts:actions=>api('/api/action-status',{method:'POST',body:JSON.stringify({actions})}),snapshot:()=>api('/api/state?site='+encodeURIComponent(site)),onChange:journalChanged});
 journalChanged(journal);
}
async function refresh(){if(!online||manualOffline)return;if(journal&&vaultUnlocked()){journal.site=site;journal.user=user;await journal.refresh();}else{baseState=await api('/api/state?site='+encodeURIComponent(site));state=structuredClone(baseState);}lastSnapshotAt=new Date().toISOString();}
async function hydrate(session){
 user=session.user;csrf=session.csrf;journal=null;queue=[];baseState=null;site=user.siteIds.includes(site)?site:user.siteIds[0];
 const linkedSite=new URL(location.href).searchParams.get('site');if(linkedSite&&user.siteIds.includes(linkedSite))site=linkedSite;
 page=user.role==='operator'?'requests':user.role==='warehouse'?'inventory':'dashboard';online=true;manualOffline=false;
 await refresh();shell();await prepareVault();
 const requested=new URL(location.href).searchParams.get('asset');if(requested&&state.assets.some(a=>a.id===requested))assetDetail(requested);
}
async function prepareVault(){
 if(vaultUnlocked())return;const profiles=await vaultProfiles(),exists=profiles.some(x=>x.id===user.id);
 form(exists?'Desbloquear copia de trabajo':'Preparar trabajo sin conexión',[{name:'passphrase',label:exists?'Frase local de acceso':'Frase local de al menos 10 caracteres',type:'password',required:true,minlength:10}],async p=>{
  if(exists){const cached=await unlockVault(user.id,p.passphrase);assertLocal(cached.user.id===user.id,'Usuario incompatible');setupJournal(cached.state,cached.queue||[],cached);}
  else{await enableVault(user,p.passphrase,{schemaVersion:2,user,site,state:baseState||state,queue:[],config,savedAt:new Date().toISOString()});setupJournal(baseState||state,[]);}
  if(online&&!manualOffline){try{await journal.refresh();lastSnapshotAt=new Date().toISOString();if(queue.some(e=>e.status==='pending'))await journal.sync();}catch(e){if(e.network)online=false;else if(e.status!==401)throw e;}}
  const ready=await offlineReady;assertLocal(ready!==false,'No se pudo preparar el arranque sin conexión. Recarga con conexión y vuelve a intentarlo.');await persist();await activateSafeUpdate();shell();
 },'Continuar','Protege los datos de este dispositivo y permite guardar trabajo sin conexión. Esta frase es local; no cambia tu contraseña de acceso.');
}
function assertLocal(condition,message){if(!condition)throw Error(message);}
async function act(type,payload,record=null){
 assertLocal(vaultUnlocked()&&journal,'Prepara o desbloquea tu copia de trabajo desde Configuración.');
 const serverOnly=['plan.generate','import.preview','import.commit','import.reverse','history.preview','history.commit','history.reverse'];
 assertLocal(!serverOnly.includes(type)||(online&&!manualOffline&&!queue.length),'Esta operación necesita conexión y los cambios sincronizados.');
 const queued=await journal.enqueue(type,payload,record);journalChanged(journal);
 if(online&&!manualOffline){try{await journal.sync();journalChanged(journal);if(journal.lastError?.network)online=false;}catch(e){if(e.network)online=false;else if(e.status===401){online=false;toast('Sesión vencida. Tus cambios quedan guardados en el dispositivo.');}else throw e;}}
 const entry=queue.find(e=>e.operationId===queued.entry.operationId);
 if(entry?.status==='conflict'){shell();toast('El cambio está guardado y requiere revisión en Sincronización.');return {queued:true,result:queued.result};}
 if(entry){shell();toast(entry.status==='confirmed'?'Servidor confirmado · copia local pendiente de actualizar':'Guardado en este dispositivo · pendiente de sincronizar');return {queued:true,result:queued.result};}
 return {result:queued.result};
}
async function activateSafeUpdate(){if(!vaultUnlocked()||queue.length||!('serviceWorker' in navigator))return;const registration=await navigator.serviceWorker.getRegistration();registration?.waiting?.postMessage('ACTIVATE_UPDATE');}
async function synchronize(){
 if(busy)return;assertLocal(vaultUnlocked()&&journal,'Desbloquea la copia local primero.');busy=true;manualOffline=false;
 try{const session=await api('/api/me');assertLocal(session.user.id===user.id,'Inicia sesión con el usuario de estos registros.');user=session.user;csrf=session.csrf;journal.user=user;online=true;await journal.sync();journalChanged(journal);online=journal.connected;lastSnapshotAt=new Date().toISOString();await activateSafeUpdate();shell();toast(queue.length?'Hay registros que necesitan revisión.':'Todos los cambios están confirmados por el servidor.');}
 catch(error){online=false;shell();toast(error.status===401?'Inicia sesión otra vez. Tus cambios locales se conservan.':error.message);}finally{busy=false;}
}
async function showLogin(){
 user=null;state=null;journal=null;queue=[];baseState=null;const profiles=await vaultProfiles().catch(()=>[]);
 app.innerHTML=`<main class="login-shell"><section class="login-box"><div class="brand">${icon('gear')}Fast <span>Up</span></div><h1>Gestión de mantenimiento</h1><p class="sub">Accede a tu espacio de trabajo.</p>${!online?'<div class="banner warn">Servidor sin conexión. Puedes abrir una copia de trabajo ya preparada en este dispositivo.</div>':''}${config.demo?'<div class="banner">Evaluación local con datos de ejemplo. Las acciones se guardan en la base de datos de este equipo.</div>':''}<form id="login-form"><label>Correo<input name="email" type="email" autocomplete="username" required value="${config.demo?'supervisor@fastup.local':''}"></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required ${config.demo?'value="FastUp-Demo-2026!"':''}></label><button class="primary" type="submit">Ingresar ${icon('arrow')}</button><div class="form-error" role="alert"></div></form>${config.demo?`<div class="demo-list">${['supervisor','technician','tech2','operator','warehouse','manager','admin'].map(id=>button(id==='tech2'?'Técnico 2':labels[id]||'Técnico','demo-user',id)).join('')}</div><p class="caption">Contraseña de demostración: FastUp-Demo-2026!</p>`:''}${profiles.length?`<hr class="divider"><p class="small muted">Copias cifradas disponibles</p><div class="demo-list">${profiles.map(x=>button(x.name,'offline-unlock',x.id)).join('')}</div>`:''}<p class="login-foot">Órdenes, activos y trabajo en terreno · Teléfono, tablet y PC</p></section></main>`;
 app.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const el=e.currentTarget;const submit=el.querySelector('button');submit.disabled=true;try{const data=Object.fromEntries(new FormData(el));const session=await api('/api/login',{method:'POST',body:JSON.stringify(data)});online=true;await hydrate(session);}catch(error){el.querySelector('.form-error').textContent=error.message;}finally{submit.disabled=false;}});
}
function navigationItem(id,label,ico,extraClass=''){
 const def=nav.find(x=>x[0]===id);if(!def||!def[3].includes(user.role))return '';
 const count=id==='requests'?state.requests.filter(x=>x.status==='Por revisar').length:id==='sync'?queue.length:0;
 return `<button class="nav-item ${page===id?'active':''} ${extraClass}" type="button" data-nav="${id}" ${page===id?'aria-current="page"':''}>${icon(ico||def[2])}<span class="nav-label">${esc(label||def[1])}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`;
}
function shell(){
 if(!user||!state)return;const allowed=nav.filter(x=>x[3].includes(user.role));if(!allowed.some(x=>x[0]===page))page=allowed[0][0];
 const plant=currentSite(),unread=state.notices.filter(x=>!x.ackBy.includes(user.id)).length;
 const maintenanceAllowed=['orders','plans','planning','procedures'].some(id=>allowed.some(x=>x[0]===id));
 app.innerHTML=`<div class="app-layout"><aside class="sidebar" id="app-sidebar"><a class="side-brand" href="#" data-nav="dashboard">${icon('gear')}<span>Fast Up</span></a><nav class="main-navigation" aria-label="Navegación principal">${navigationItem('dashboard','Inicio','home')}${navigationItem('assets','Activos','motor')}${maintenanceAllowed?`<button type="button" class="nav-group" data-do="toggle-maintenance" aria-expanded="${menuExpanded}">${icon('tool')}<span>Mantenimiento</span>${icon(menuExpanded?'chevron-up':'chevron-down')}</button><div class="nav-children" ${menuExpanded?'':'hidden'}>${navigationItem('orders','Órdenes de trabajo','', 'child')}${navigationItem('plans','Preventivo','','child')}${can('supervisor','technician','manager')?`<button type="button" class="nav-item child ${page==='orders'&&typeFilter==='Correctiva'?'active':''}" data-do="corrective"><span class="nav-label">Correctivo</span></button>`:''}${navigationItem('condition','Por condición','','child')}${navigationItem('procedures','Procedimientos','','child')}${navigationItem('planning','Planificación','','child')}</div>`:''}${navigationItem('requests','Avisos de falla','message')}<div class="nav-divider"></div>${navigationItem('inventory','Inventario','package')}${navigationItem('reports','Reportes','chart')}${navigationItem('resources','Recursos','tool')}${navigationItem('admin','Usuarios y permisos','users')}${navigationItem('settings','Configuración','settings')}</nav><div class="side-bottom">${navigationItem('sync','Sincronización','cloud')}<div class="plant-label">${icon('factory')}<span>${esc(plant?.name)}</span></div><span class="small">${config.demo?'Entorno de evaluación':'Gestión de mantenimiento'}</span></div></aside><div class="main-column"><header class="topbar"><button class="ghost mobile-menu" type="button" data-do="menu" aria-label="Abrir menú">${icon('menu')}</button><div class="top-spacer"></div><label class="top-search">${icon('search')}<input id="global-search" aria-label="Buscar activo u orden" placeholder="Buscar…" value="${esc(query)}"></label><div class="top-separator"></div><button type="button" class="notification-button" data-nav="notices" aria-label="Alertas">${icon('bell')}${unread?'<span class="notification-dot"></span>':''}</button><div class="top-separator"></div><div class="profile-control"><button type="button" class="profile-button" data-do="profile" aria-expanded="${profileOpen}"><span class="avatar">${icon('user')}</span><span>${esc(labels[user.role])}</span>${icon('chevron-down')}</button>${profileOpen?`<div class="profile-menu"><strong>${esc(user.name)}</strong><span class="small muted">${esc(user.email)}</span>${button('Configuración','open-settings')}${button('Cerrar sesión','logout','','', 'logout')}</div>`:''}</div></header><main class="workspace"><div class="breadcrumb">${esc(plant?.name)}<span>/</span>${esc(nav.find(x=>x[0]===page)?.[1])}${user.siteIds.length>1?`<select id="site-picker" aria-label="Cambiar planta">${state.sites.map(s=>`<option value="${esc(s.id)}" ${s.id===site?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`:''}</div>${!online||manualOffline?'<div class="banner warn"><strong>Trabajo sin conexión.</strong> Los cambios se guardan en este dispositivo y se enviarán cuando vuelva la conexión.</div>':''}${queue.length?`<div class="banner pending-banner"><span>${queue.filter(e=>e.status!=='confirmed').length} cambios por sincronizar${queue.some(e=>e.status==='conflict')?' · Hay registros por revisar':''}</span>${link('Ver detalles','goto-sync','')}</div>`:''}<div id="page-content"></div></main></div><footer class="app-statusbar"><span>${icon('user')}<span>Usuario: <strong>${esc(labels[user.role])}</strong></span></span><span>${icon('database')}<span id="connection-label">Servidor: ${online&&!manualOffline?'En línea':'Sin conexión'}</span><i id="connection-dot" class="status-dot ${online&&!manualOffline?'':'offline'}"></i></span><button type="button" data-nav="sync">${icon('refresh')}<span>Sincronización: ${queue.some(e=>e.status==='conflict')?'Requiere revisión':queue.length?`${queue.length} pendientes`:vaultUnlocked()?'Correcta':'Copia local bloqueada'}</span><i class="status-dot ${queue.length||!vaultUnlocked()?'offline':''}"></i></button><span class="status-version">v1.1.0</span></footer><button class="sidebar-overlay" type="button" data-do="menu" aria-label="Cerrar menú"></button></div>`;
 renderPage();app.querySelector('#global-search')?.addEventListener('change',e=>{query=e.target.value;const q=normalize(query);page=state.orders.some(o=>normalize(o.code+' '+o.title).includes(q))&&!state.assets.some(a=>normalize(a.code+' '+a.name).includes(q))?'orders':'assets';shell();});
 app.querySelector('#site-picker')?.addEventListener('change',async e=>{const previousSite=site;try{assertLocal(online&&!manualOffline,'Cambiar de planta requiere conexión para descargar su información.');site=e.target.value;await refresh();shell();}catch(error){site=previousSite;if(journal)journal.site=site;e.target.value=site;toast(error.message);}});
}
const requiresServer=new Set(['new-user','edit-user','new-site','import','import-detail','commit-import','reverse-import','generate-pm','system-health','export-site']);
function renderPage(){const root=app.querySelector('#page-content');const views={dashboard:dashboardView,orders:ordersView,requests:requestsView,assets:assetsView,plans:plansView,inventory:inventoryView,planning:planningView,procedures:proceduresView,condition:conditionView,reports:reportsView,resources:resourcesView,notices:noticesView,sync:syncView,admin:adminView,settings:settingsView};root.innerHTML=views[page]();root.querySelector('#local-search')?.addEventListener('input',e=>{query=e.target.value;updateList();});root.querySelector('#status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;updateList();});if(page==='reports')loadReports();if(page==='admin')loadIntegrations();if(!online||manualOffline)root.querySelectorAll('[data-do]').forEach(control=>{if(requiresServer.has(control.dataset.do)){control.disabled=true;control.title='Disponible con conexión al servidor';control.setAttribute('aria-label',control.textContent+' · requiere conexión');}});}
function updateList(){const el=app.querySelector('#list-region');if(el)el.innerHTML=page==='orders'?orderList():page==='assets'?assetList():requestList();}
function filters(placeholder,statuses=[]){return `<div class="toolbar"><input id="local-search" type="search" aria-label="Buscar" placeholder="${esc(placeholder)}" value="${esc(query)}">${statuses.length?`<select id="status-filter" aria-label="Estado"><option value="">Todos los estados</option>${statuses.map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select>`:''}</div>`;}
function ordersView(){return heading(user.role==='technician'?'Mis órdenes de trabajo':'Órdenes de trabajo','Prioriza, asigna y da seguimiento al mantenimiento.',can('supervisor')?button('Crear orden','new-order','',true,'plus'):'')+filters('Buscar orden, activo o ubicación',['Registrada','Asignada','En proceso','En espera de repuesto','En prueba','Finalizada','Cancelada'])+`<div id="list-region">${orderList()}</div>`;}
function orderList(){const rows=state.orders.filter(o=>(user.role!=='technician'||o.technicianIds.includes(user.id))&&normalize(o.code+' '+o.title+' '+name('assets',o.assetId)+' '+name('assets',o.assetId,'location')).includes(normalize(query))&&(!statusFilter||o.status===statusFilter)&&(!typeFilter||o.type===typeFilter));return `<p class="count">${rows.length} órdenes · ${rows.filter(o=>o.priority==='Alta'&&!closed(o)).length} abiertas de prioridad alta</p><div class="desktop-orders">${table(['Orden','Activo / trabajo','Estado','Prioridad','Responsable','Vencimiento'],rows.map(o=>`<tr><td>${link(o.code,'order',o.id)}</td><td><strong>${esc(name('assets',o.assetId))}</strong><div class="sub">${esc(o.title)}</div></td><td>${badge(o.status)}</td><td class="${o.priority==='Alta'?'priority-high':'priority-normal'}">${esc(o.priority)}</td><td>${esc(o.technicianIds.map(id=>name('users',id)).join(', ')||'Sin asignar')}</td><td>${due(o)?'<span class="badge red">Vencida</span><br>':''}<span class="small">${fmt(o.dueAt,false)}</span></td></tr>`))}</div><div class="phone-list">${rows.map(o=>`<article class="phone-order"><div class="row between">${link(o.code,'order',o.id)}${badge(o.status)}</div><h3>${esc(name('assets',o.assetId))}</h3><p class="small muted">${esc(o.title)}</p><div class="row between sub"><span>${esc(o.technicianIds.map(id=>name('users',id)).join(', ')||'Sin asignar')}</span><span class="${o.priority==='Alta'?'priority-high':''}">Prioridad ${esc(o.priority)}</span></div><p class="small ${due(o)?'priority-high':'muted'}">${due(o)?'Vencida · ':''}${fmt(o.dueAt,false)}</p></article>`).join('')||empty('No hay órdenes con estos filtros')}</div>`;}
function requestsView(){return heading('Avisos de falla','Registra anomalías y consulta el resultado de su revisión.',can('operator','technician','supervisor')?button('Reportar falla','new-request','',true,'plus'):'')+filters('Buscar aviso o descripción',['Por revisar','Aceptado','Vinculado','Rechazado'])+`<div id="list-region">${requestList()}</div>`;}
function requestList(){return table(['Aviso','Activo / descripción','Condición','Estado','Seguimiento'],state.requests.filter(r=>normalize(r.code+' '+r.description).includes(normalize(query))&&(!statusFilter||statusFilter===r.status)).map(r=>`<tr><td>${esc(r.code)}<div class="sub">${fmt(r.occurredAt)}</div></td><td><strong>${esc(name('assets',r.assetId))}</strong><div class="sub">${esc(r.description)}</div></td><td>${esc(r.condition)}</td><td>${badge(r.status)}</td><td>${can('supervisor')&&r.status==='Por revisar'?button('Revisar','triage',r.id):r.orderId?can('supervisor')?link(name('orders',r.orderId,'code'),'order',r.orderId):esc(name('orders',r.orderId,'code')):esc(r.resolution||'Pendiente de revisión')}</td></tr>`));}
function assetsView(){return heading('Activos','Equipos, ubicaciones, historial e identificación.',can('supervisor')?button('Registrar activo','new-asset','',true,'plus'):'')+filters('Buscar código, equipo o ubicación')+`<div id="list-region">${assetList()}</div>`;}
function assetList(){return table(['Activo','Ubicación / jerarquía','Estado','Criticidad','Medidor'],state.assets.filter(a=>normalize([a.code,a.name,a.location,a.equipmentType,a.brand,a.serial].join(' ')).includes(normalize(query))).map(a=>`<tr><td>${link(a.code,'asset',a.id)}<div><strong>${esc(a.name)}</strong></div></td><td>${esc(a.location)}<div class="sub">${a.parentId?esc(name('assets',a.parentId)):'Nivel principal'}</div></td><td>${badge(a.status)}</td><td>${esc(a.criticality)}</td><td>${n(a.meter)} ${esc(a.unit)}</td></tr>`));}
function plansView(){return heading('Mantenimiento preventivo','Reglas por calendario o uso, con historial preservado.',can('supervisor')?button('Generar órdenes','generate-pm')+button('Crear plan','new-plan','',true,'plus'):'')+table(['Plan','Activo','Regla','Próximo vencimiento','Estado',''],state.plans.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="sub">${esc(name('templates',p.templateId))}</div></td><td>${esc(name('assets',p.assetId))}</td><td>${p.mode==='fixed'?'Fija':'Desde finalización'}<div class="sub">${p.intervalDays?`${p.intervalDays} días`:''}${p.intervalMeter?` / ${p.intervalMeter} ${esc(name('assets',p.assetId,'unit'))}`:''}</div></td><td>${p.nextDue?fmt(p.nextDue,false):''}${p.nextMeter!==null?`<div class="sub">Medidor: ${n(p.nextMeter)}</div>`:''}</td><td>${badge(p.active?'Activo':'Suspendido')}</td><td>${can('supervisor')?button(p.active?'Suspender':'Activar','toggle-plan',p.id):''}</td></tr>`))+`<p class="caption">La generación es explícita. Cada plan mantiene como máximo una orden abierta; los períodos fijos omitidos se registran a través del vencimiento de la orden generada. Finalizar una orden flotante calcula su siguiente intervalo.</p>`;}
function inventoryView(){return heading('Bodega y repuestos','Stock, reservas, entregas, devoluciones y costos históricos.',can('warehouse','supervisor')?button('Registrar repuesto','new-part','',true,'plus'):'')+table(['Repuesto','Ubicación','Stock / mínimo','Reservado','Costo unitario',''],state.parts.map(p=>`<tr><td><strong>${esc(p.code)}</strong><div class="sub">${esc(p.name)}</div></td><td>${esc(p.bin)}</td><td>${p.stock<p.minStock?badge(`${n(p.stock)} / ${n(p.minStock)}`):`${n(p.stock)} / ${n(p.minStock)}`} ${esc(p.unit)}</td><td>${n(state.reservations.filter(r=>r.partId===p.id&&r.status==='Activa').reduce((n,r)=>n+r.quantity,0))}</td><td>${p.cost===undefined?'Restringido':money(p.cost,p.currency)}</td><td>${can('warehouse')?button('Movimiento','stock',p.id):''}${can('warehouse','supervisor')?button('Reservar','reserve',p.id):''}</td></tr>`))+`<hr class="divider"><h3 class="panel-heading">Movimientos recientes</h3>${table(['Fecha','Repuesto','Movimiento','Cantidad','Orden','Responsable'],[...state.movements].reverse().slice(0,50).map(m=>`<tr><td>${fmt(m.occurredAt)}</td><td>${esc(name('parts',m.partId))}</td><td>${esc(({receipt:'Recepción',issue:'Entrega',return:'Devolución',adjustment:'Ajuste'})[m.type])}</td><td>${n(m.quantity)}</td><td>${esc(name('orders',m.orderId,'code'))}</td><td>${esc(name('users',m.authorId))}</td></tr>`))}<hr class="divider"><h3 class="panel-heading">Reservas activas</h3>${table(['Repuesto','Orden','Cantidad',''],state.reservations.filter(r=>r.status==='Activa').map(r=>`<tr><td>${esc(name('parts',r.partId))}</td><td>${esc(name('orders',r.orderId,'code'))}</td><td>${n(r.quantity)}</td><td>${can('warehouse','supervisor')?button('Liberar','release-reservation',r.id):''}</td></tr>`))}`;}
function conditionView(){
 const inspections=state.orders.filter(o=>o.type==='Inspección'),checks=inspections.flatMap(o=>o.checks.map(c=>({...c,order:o,task:o.tasks.find(t=>t.id===c.taskId)})));
 return heading('Mantenimiento por condición','Inspecciones, mediciones y seguimiento de hallazgos.',can('supervisor')?button('Crear inspección','new-inspection','',true,'plus'):'')+`<div class="stats">${stat('Inspecciones abiertas',inspections.filter(o=>!closed(o)).length)}${stat('Hallazgos registrados',checks.filter(c=>c.result==='Fail').length)}${stat('Lecturas de uso',state.readings.length)}</div><section class="panel"><h3>Órdenes de inspección</h3>${table(['Orden','Activo','Trabajo','Estado'],inspections.map(o=>`<tr><td>${link(o.code,'order',o.id)}</td><td>${esc(name('assets',o.assetId))}</td><td>${esc(o.title)}</td><td>${badge(o.status)}</td></tr>`))}</section><hr class="divider"><h3 class="panel-heading">Mediciones y resultados de inspección</h3>${table(['Fecha','Activo / orden','Punto','Valor / rango','Resultado','Seguimiento'],checks.map(c=>`<tr><td>${fmt(c.at)}</td><td>${esc(name('assets',c.order.assetId))}<div>${link(c.order.code,'order',c.order.id)}</div></td><td>${esc(c.task?.label)}</td><td>${c.task?.type==='reading'?`${esc(c.value)} ${esc(c.task.unit)}<div class="small">${esc(c.task.min??'—')} a ${esc(c.task.max??'—')}</div>`:'Verificación'}</td><td>${badge(c.result)}</td><td>${c.followUpId?link(name('orders',c.followUpId,'code'),'order',c.followUpId):esc(c.note||'—')}</td></tr>`))}<p class="caption">Los límites se toman del procedimiento copiado a cada orden. Un resultado fuera de rango exige registrar una falla y genera una orden correctiva vinculada.</p><hr class="divider"><h3 class="panel-heading">Últimas lecturas de uso</h3>${table(['Activo','Fecha','Lectura','Acumulado'],[...state.readings].sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)).slice(0,25).map(r=>`<tr><td>${link(name('assets',r.assetId),'asset',r.assetId)}</td><td>${fmt(r.occurredAt)}</td><td>${n(r.value)} ${esc(r.unit)}</td><td>${n(r.effectiveValue)}</td></tr>`))}`;
}
function proceduresView(){return heading('Procedimientos','Instrucciones y listas de inspección copiadas a cada orden.',can('supervisor')?button('Crear procedimiento','new-template','',true,'plus'):'')+`<div class="resource-grid">${state.templates.map(t=>`<article class="resource-item">${badge('Versión '+t.version)}<h3>${esc(t.name)}</h3><p class="sub">${esc(t.instructions)}</p><ol>${t.tasks.map(x=>`<li class="sub">${esc(x.label)} ${x.type==='reading'?`(${esc(x.unit)}; ${x.min??'—'} a ${x.max??'—'})`:''}</li>`).join('')}</ol></article>`).join('')||empty('Sin procedimientos')}</div>`;}
function planningView(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+i);return d;});return heading('Planificación','Carga por responsable y próxima semana.',can('supervisor')?button('Crear orden','new-order','',true,'plus'):'')+`<div class="month-grid">${days.map(d=>`<div class="day-column"><div class="day-label">${fmt(d,false)}</div>${state.orders.filter(o=>!closed(o)&&new Date(o.plannedAt).toDateString()===d.toDateString()).map(o=>`<button type="button" class="calendar-order" data-do="order" data-id="${o.id}"><strong>${esc(o.code)}</strong><br>${esc(o.title)}<br>${n(o.estimatedHours)} h · ${esc(o.technicianIds.map(id=>name('users',id)).join(', ')||'Sin asignar')}</button>`).join('')}</div>`).join('')}</div><hr class="divider"><h3 class="panel-heading">Disponibilidad y carga abierta</h3>${table(['Técnico','Especialidad / turno','Disponibilidad','Horas estimadas asignadas','Órdenes abiertas'],state.users.filter(u=>u.role==='technician').map(u=>{const orders=state.orders.filter(o=>!closed(o)&&o.technicianIds.includes(u.id));return `<tr><td>${esc(u.name)}</td><td>${esc(u.specialty)} · ${esc(u.shift)}</td><td>${badge(u.available?'Disponible':'No disponible')}</td><td>${n(orders.reduce((n,o)=>n+o.estimatedHours,0))} h</td><td>${orders.length}</td></tr>`;}))}<p class="caption">La carga muestra horas por orden asignada a cada técnico; es una referencia de planificación, no un calendario de asistencia o nómina.</p>`;}
function dashboardView(){
 const open=state.orders.filter(o=>!closed(o)),stopped=state.assets.filter(a=>a.status==='Detenido');
 const modules=[['assets','Activos','Registrar y consultar equipos','motor'],['orders','Órdenes de mantenimiento','Gestionar intervenciones','clipboard'],['inventory','Inventario','Control de repuestos','cubes'],['reports','Reportes','Indicadores y análisis','chart']].filter(([id])=>nav.find(n=>n[0]===id)?.[3].includes(user.role));
 return heading('Inicio','Gestión de mantenimiento industrial')+`<section class="home-modules" aria-label="Módulos de mantenimiento">${modules.map(([id,title,description,ico])=>`<button type="button" class="module-card" data-nav="${id}"><span class="module-icon">${icon(ico)}</span><h2>${title}</h2><p>${description}</p><span class="module-arrow">${icon('arrow-right')}</span></button>`).join('')}</section><section class="home-overview" aria-label="Actividad de mantenimiento"><div class="section-heading"><h2>Resumen operativo</h2><span class="small muted">${lastSnapshotAt?'Última actualización: '+fmt(lastSnapshotAt):'Información disponible en este dispositivo'}</span></div><div class="home-metrics">${stat('Órdenes abiertas',open.length)}${stat('Vencidas',open.filter(due).length)}${stat('Prioridad alta',open.filter(o=>o.priority==='Alta').length)}${stat('Equipos detenidos',stopped.length)}</div><div class="two-col"><section class="panel"><div class="row between"><h3>Trabajo prioritario</h3>${link('Ver órdenes','goto-orders','')}</div>${open.filter(o=>o.priority==='Alta'||due(o)).slice(0,4).map(o=>`<div class="attention-row"><div>${link(o.code,'order',o.id)}<p>${esc(o.title)}</p><span class="small muted">${esc(name('assets',o.assetId))}</span></div>${badge(o.status)}</div>`).join('')||empty('No hay trabajo prioritario pendiente')}</section><section class="panel"><div class="row between"><h3>Estado de la operación</h3>${badge(online&&!manualOffline?'Conectado':'Sin conexión')}</div><div class="operation-row"><span>Activos registrados</span><strong>${state.assets.length}</strong></div><div class="operation-row"><span>Avisos por revisar</span><strong>${state.requests.filter(r=>r.status==='Por revisar').length}</strong></div><div class="operation-row"><span>Registros por sincronizar</span><strong>${queue.length}</strong></div><div class="operation-row"><span>Planes preventivos activos</span><strong>${state.plans.filter(p=>p.active).length}</strong></div></section></div></section><div class="factory-watermark" aria-hidden="true">${icon('factory')}</div>`;
}
function settingsView(){return heading('Configuración','Tu espacio de trabajo, conexión y continuidad operativa.')+`<div class="two-col"><section class="panel"><h3>Copia de trabajo</h3><p class="sub">${vaultUnlocked()?'La copia cifrada está desbloqueada en este dispositivo.':'Prepara o desbloquea tu copia para trabajar sin conexión.'}</p><div class="settings-actions">${button(vaultUnlocked()?'Guardar copia actual':'Preparar / desbloquear','vault','',true)}${button('Ver sincronización','goto-sync')}</div><p class="caption">${lastSnapshotAt?'Última actualización: '+fmt(lastSnapshotAt):'La información se descargará al conectar con el servidor.'}</p></section><section class="panel"><h3>Conexión</h3><p class="sub">${online&&!manualOffline?'Servidor disponible. Puedes consultar y registrar trabajo.':'Estás trabajando sobre la copia local.'}</p><div class="settings-actions">${button(manualOffline?'Volver a conectar':'Trabajar sin conexión','toggle-offline','',true)}${button('Comprobar y sincronizar','sync')}</div><p class="caption">Usuarios, permisos, importación de archivos y tareas del servidor requieren conexión. El trabajo guardado queda protegido en este dispositivo.</p></section>${can('supervisor')?`<section class="panel"><h3>Reglas de la planta</h3><p class="sub">Generación preventiva y alertas de revisión y atraso.</p><div class="settings-actions">${user.role==='admin'?button('Configurar automatización','site-policy'):''}${button('Planificación preventiva','open-plans')}</div></section>`:''}<section class="panel"><h3>Sesión</h3><p class="sub">${esc(user.name)} · ${esc(labels[user.role])}</p><p class="caption">${esc(user.email)} · ${esc(currentSite()?.name)}</p><div class="settings-actions">${button('Volver a iniciar sesión','reauth')}${button('Cerrar sesión','logout')}</div></section></div>`;}
function reportsView(){return heading('Reportes de mantenimiento','Indicadores con período, definición y acceso a los registros.',button('Imprimir / PDF','print'))+`<div class="filter-row"><label>Activo<select id="report-asset"><option value="">Todos los activos</option>${optHtml(options(state.assets.map(a=>({...a,name:a.code+' · '+a.name}))),'')}</select></label><label>Tipo de equipo<select id="report-equipment-type"><option value="">Todos los equipos</option>${optHtml([...new Set(state.assets.map(a=>a.equipmentType||'Otro'))].sort(),'')}</select></label><label>Tipo de trabajo<select id="report-type"><option value="">Todos los tipos</option>${optHtml(['Correctiva','Preventiva','Inspección','Mejora'],'')}</select></label><label>Desde (UTC)<input type="date" id="report-from" value="${new Date(Date.now()-30*86400000).toISOString().slice(0,10)}"></label><label>Hasta (UTC)<input type="date" id="report-to" value="${new Date().toISOString().slice(0,10)}"></label>${button('Aplicar','load-reports','',true)}${button('Exportar CSV','export-report')}${can('supervisor')?button('Registrar horas operativas','exposure'):''}</div><div id="report-data" aria-live="polite">Cargando indicadores…</div>`;}
let lastReport;
function reliabilityTable(r){return `<hr class="divider"><h3 class="panel-heading">Confiabilidad y restauración</h3>${table(['Activo','Horas operativas verificadas','MTBF (h)','Restauración media (h)'],r.assets.map(a=>`<tr><td>${esc(a.code)}</td><td>${a.runtimeHours===null?'Cobertura incompleta':n(a.runtimeHours)}</td><td>${a.mtbfHours===null?'Datos insuficientes':n(a.mtbfHours)}</td><td>${a.meanRestorationHours===null?'Sin retornos en período':n(a.meanRestorationHours)}</td></tr>`))}`;}
async function loadReports(){const target=app.querySelector('#report-data');if(!target)return;try{const from=app.querySelector('#report-from').value,to=app.querySelector('#report-to').value;const assetId=app.querySelector('#report-asset').value,workType=app.querySelector('#report-type').value,equipmentType=app.querySelector('#report-equipment-type').value;const r=online&&!manualOffline?await api(`/api/reports?site=${encodeURIComponent(site)}&from=${from}&to=${to}&assetId=${encodeURIComponent(assetId)}&workType=${encodeURIComponent(workType)}&equipmentType=${encodeURIComponent(equipmentType)}`):localReports(state,site,from,to,{assetId,workType,equipmentType});lastReport=r;const c=currentSite()?.currency||'CLP';target.innerHTML=`${!online||manualOffline?'<div class="banner warn">Informe de la copia local. Incluye trabajo pendiente de sincronizar; la información puede haber cambiado en el servidor.</div>':''}<div class="stats">${stat('Órdenes abiertas',r.open,'Situación actual')}${stat('Órdenes vencidas',r.overdue,'Situación actual')}${stat('Horas de trabajo',n(r.laborHours),'Entradas de técnicos en período')}${stat('Preventivos a tiempo',r.preventiveDue?Math.round(r.preventiveOnTime/r.preventiveDue*100)+'%':'—',`${r.preventiveOnTime} / ${r.preventiveDue} vencimientos`)}</div><div class="two-col"><section class="panel"><h3 class="panel-heading">Costos registrados</h3><p class="sub">Mano de obra: <strong>${money(r.laborCost,c)}</strong></p>${Object.entries(r.partsByCurrency).map(([currency,v])=>`<p class="sub">Repuestos (${esc(currency)}): <strong>${money(v,currency)}</strong></p>`).join('')}${Object.entries(r.expensesByCurrency).map(([currency,v])=>`<p class="sub">Servicios / otros (${esc(currency)}): <strong>${money(v,currency)}</strong></p>`).join('')}<p class="caption">${esc(r.definitions.costs)}</p>${r.unknownLaborCostEntries?`<p class="caption">${r.unknownLaborCostEntries} intervenciones sin tarifa histórica; costo desconocido.</p>`:''}</section><section class="panel"><h3 class="panel-heading">Órdenes finalizadas en el período</h3><p class="sub">Finalizadas: <strong>${r.closed}</strong> · A tiempo: <strong>${r.onTime}</strong></p><p class="caption">${esc(r.definitions.labor)}</p><p class="caption">${esc(r.definitions.downtime)}</p></section></div><hr class="divider"><h3 class="panel-heading">Detenciones por activo</h3>${table(['Activo','Planificadas (h)','No planificadas (h)','Fallas iniciadas',''],r.assets.map(a=>`<tr><td>${esc(a.code)} · ${esc(a.name)}</td><td>${n(a.plannedHours)}</td><td>${n(a.unplannedHours)}</td><td>${a.failures}</td><td>${link('Ver registros','asset',a.id)}</td></tr>`))}${reliabilityTable(r)}<p class="caption">${esc(r.definitions.reliability)}</p><p class="caption">${esc(r.definitions.period)}</p>`;}catch(error){target.innerHTML=`<div class="banner warn">${esc(error.message)}</div>`;}}
function resourcesView(){return heading('Recursos y seguimiento','Herramientas, contratistas, calibraciones y garantías.',can('supervisor')?button('Registrar recurso','new-resource','',true,'plus'):'')+table(['Recurso','Categoría','Referencia / activo','Responsable','Fecha','Estado',''],state.resources.map(r=>`<tr><td><strong>${esc(r.name)}</strong><div class="sub">${esc(r.note)}</div></td><td>${esc(({tool:'Herramienta',contractor:'Contratista',calibration:'Calibración',warranty:'Garantía'})[r.category])}</td><td>${esc(r.reference)}<div class="sub">${esc(name('assets',r.assetId))}</div></td><td>${esc(name('users',r.holderId))}</td><td>${fmt(r.dueAt,false)}</td><td>${badge(r.status)}</td><td>${can('supervisor')?button('Actualizar','resource-update',r.id):''}</td></tr>`));}
function noticesView(){const derived=state.orders.filter(due).map(o=>({title:`Orden vencida: ${o.code}`,body:o.title,orderId:o.id}));return heading('Alertas','Revisa las novedades y confirma su lectura.')+`<div class="stack">${[...state.notices,...derived].map(x=>`<article class="panel"><div class="row between"><h3>${esc(x.title)}</h3>${x.id?x.ackBy.includes(user.id)?badge('Leída'):button('Marcar leída','ack',x.id):badge('Atención')}</div><p class="sub">${esc(x.body)}</p>${x.orderId&&state.orders.some(o=>o.id===x.orderId)?link('Abrir orden','order',x.orderId):''}</article>`).join('')||empty('No hay alertas')}</div>`;}
function syncView(){return heading('Sincronización y copia local','Los registros se eliminan de la cola solo después de la confirmación del servidor.',button('Sincronizar ahora','sync','',true,'cloud'))+`<div class="banner ${online&&!manualOffline?'':'warn'}">${online&&!manualOffline?'Conectado':'Sin conexión'} · ${queue.length} pendientes · ${vaultUnlocked()?'Copia cifrada desbloqueada':'Copia cifrada bloqueada'}</div><div class="row">${button(vaultUnlocked()?'Guardar copia actual':'Preparar / desbloquear copia','vault')}${button('Exportar pendientes cifrados','export-pending')+button('Recuperar archivo cifrado','import-pending')}${button('Volver a iniciar sesión','reauth')}</div><hr class="divider">${table(['Registro','Fecha','Estado','Detalle',''],queue.map(q=>`<tr><td>${esc(q.type)}</td><td>${fmt(q.occurredAt)}</td><td>${badge(q.status==='conflict'?'Requiere revisión':q.status==='confirmed'?'Confirmado · actualizar copia':'Pendiente')}</td><td>${esc(q.lastError||q.operationId)}</td><td>${q.status==='conflict'?button('Revisar','review-local',q.operationId):''}</td></tr>`))}<hr class="divider"><h3 class="panel-heading">Conflictos registrados en el servidor</h3>${table(['Operación','Usuario','Estado',''],state.conflicts.map(c=>`<tr><td>${esc(c.action.type)}<div class="sub">${esc(c.error)}</div></td><td>${esc(name('users',c.userId))}</td><td>${badge(c.status)}</td><td>${button('Revisar','server-conflict',c.id)}</td></tr>`))}<p class="caption">La copia incluye datos visibles para tu usuario y archivos que hayas adjuntado mientras trabajabas sin conexión. No se descargan automáticamente todos los archivos del servidor. La aplicación debe haberse abierto en este dispositivo antes de trabajar sin red.</p>`;}
function adminView(){return heading('Administración','Accesos, plantas, migración, trazabilidad e integración.',button('Nuevo usuario','new-user','',true,'plus'))+table(['Usuario','Rol','Plantas','Estado',''],state.users.map(u=>`<tr><td>${esc(u.name)}<div class="sub">${esc(u.email)}</div></td><td>${esc(labels[u.role])}</td><td>${u.siteIds.length}</td><td>${badge(u.active?'Activo':'Desactivado')}</td><td>${button('Editar','edit-user',u.id)}</td></tr>`))+`<hr class="divider"><div class="row">${button('Nueva planta','new-site')+button('Automatización','site-policy')+button('Estado del sistema','system-health')}${button('Importar Excel / CSV','import')}${button('Exportar datos de planta','export-site')}${button('Ver auditoría','audit')}</div><hr class="divider"><h3 class="panel-heading">Lotes de importación</h3>${table(['Archivo','Destino','Estado','Filas / creadas',''],state.imports.map(i=>`<tr><td>${esc(i.source)}</td><td>${esc(i.kind)}</td><td>${badge(i.status)}</td><td>${i.rows.length} / ${i.createdIds.length}</td><td>${button('Revisar','import-detail',i.id)}</td></tr>`))}<hr class="divider"><h3 class="panel-heading">Integración de eventos</h3><div id="integration-state" class="small muted">Cargando…</div><p class="caption">La API REST y la cola de eventos están disponibles. ERP, BI, correo, SSO y sensores externos requieren conexión y configuración del sistema correspondiente; no se simula una integración activa.</p>`;}
async function loadIntegrations(){const target=app.querySelector('#integration-state');if(!target)return;if(!online||manualOffline){target.innerHTML='<div class="banner">La comprobación de integraciones estará disponible al conectar. Los usuarios y permisos se muestran desde la última copia descargada.</div>';return;}try{const result=await api('/api/integrations?site='+site);target.innerHTML=`${badge(result.configured?'Webhook configurado':'Sin webhook externo')}<p class="sub">${result.events.filter(e=>e.delivered_at).length} entregados · ${result.events.filter(e=>!e.delivered_at).length} en cola</p>${table(['Evento','Intentos','Último error'],result.events.filter(e=>e.last_error).slice(0,5).map(e=>`<tr><td>${esc(e.id)}</td><td>${e.attempts}</td><td>${esc(e.last_error)}</td></tr>`))}`;}catch(error){target.textContent=error.message;}}

function openDialog(title,content,subtitle='',wide=false){modal.className=wide?'wide-dialog':'';modal.innerHTML=`<header class="dialog-head"><div><h2>${esc(title)}</h2>${subtitle?`<p class="sub">${esc(subtitle)}</p>`:''}</div><button class="ghost" type="button" data-do="close" aria-label="Cerrar">${icon('close')}</button></header><div class="dialog-body">${content}</div>`;if(!modal.open)modal.showModal();}
const options=(list,label='name')=>list.map(x=>({value:x.id,label:x[label]}));
const optHtml=(list,value)=>list.map(o=>{const v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${(Array.isArray(value)?value.map(String).includes(String(v)):String(v)===String(value))?'selected':''}>${esc(l)}</option>`;}).join('');
const assetField=(value)=>({name:'assetId',label:'Activo',type:'select',required:true,value,options:options(state.assets.filter(a=>a.status!=='Retirado').map(a=>({...a,name:`${a.code} · ${a.name}`})))});
const orderField=()=>({name:'orderId',label:'Orden de trabajo',type:'select',required:true,options:options(state.orders.filter(o=>!closed(o)).map(o=>({...o,name:`${o.code} · ${o.title}`})))});
function form(title,fields,onSubmit,submit='Guardar',note=''){
 const draftKey=site+'|'+title+'|'+activeContext;const canDraft=vaultUnlocked()&&journal&&!fields.some(f=>f.type==='password');
 if(canDraft&&journal.drafts[draftKey])fields=fields.map(f=>({...f,value:journal.drafts[draftKey][f.name]??f.value}));
 const markup=fields.map(f=>{const attrs=`name="${f.name}" ${f.required?'required':''} ${f.min!==undefined?`min="${f.min}"`:''} ${f.step?`step="${f.step}"`:''} ${f.minlength?`minlength="${f.minlength}"`:''}`;const label=`<span>${esc(f.label)}${f.required?' *':''}</span>`;if(f.type==='checkbox')return `<label class="check ${f.wide?'wide':''}"><input type="checkbox" ${attrs} ${f.value?'checked':''}>${label}</label>`;return `<label class="${f.wide?'wide':''}">${label}${f.type==='select'?`<select ${attrs} ${f.multiple?'multiple':''}>${!f.required?'<option value="">—</option>':''}${optHtml(f.options||[],f.value)}</select>`:f.type==='textarea'?`<textarea ${attrs} placeholder="${esc(f.placeholder||'')}">${esc(f.value||'')}</textarea>`:`<input ${attrs} type="${f.type||'text'}" value="${esc(f.value??'')}" placeholder="${esc(f.placeholder||'')}">`}${f.help?`<span class="small muted">${esc(f.help)}</span>`:''}</label>`;}).join('');
 openDialog(title,`${note?`<p class="banner">${esc(note)}</p>`:''}<form id="entity-form"><div class="form-grid">${markup}</div><div class="form-error" role="alert"></div>${canDraft?'<p class="draft-state caption" role="status">Borrador protegido en este dispositivo</p>':''}<div class="form-actions">${button('Cancelar','close')}<button type="submit" class="primary">${esc(submit)}</button></div></form>`);
 if(canDraft)modal.querySelector('#entity-form').addEventListener('input',async event=>{
  const el=event.currentTarget,values=Object.fromEntries(new FormData(el));fields.forEach(f=>{if(f.type==='checkbox')values[f.name]=el.elements[f.name].checked;if(f.multiple)values[f.name]=[...el.elements[f.name].selectedOptions].map(o=>o.value);});
  journal.drafts[draftKey]=values;try{await journal.persist();const status=el.querySelector('.draft-state');if(status)status.textContent='Borrador guardado en este dispositivo';}catch(error){el.querySelector('.form-error').textContent='No se pudo proteger el borrador: '+error.message;}
 });
 modal.querySelector('#entity-form').addEventListener('submit',async e=>{e.preventDefault();const el=e.currentTarget,submitButton=el.querySelector('[type=submit]');submitButton.disabled=true;const data=Object.fromEntries(new FormData(el));fields.forEach(f=>{if(f.type==='checkbox')data[f.name]=el.elements[f.name].checked;if(f.multiple)data[f.name]=[...el.elements[f.name].selectedOptions].map(o=>o.value);if(f.type==='datetime-local'&&data[f.name])data[f.name]=new Date(data[f.name]).toISOString();});try{await onSubmit(data);if(canDraft){delete journal.drafts[draftKey];await journal.persist();}modal.close();shell();toast(queue.length?'Guardado en este dispositivo · revisa la sincronización':'Registro guardado');}catch(error){el.querySelector('.form-error').textContent=error.message;if(error.status===409)await refresh().catch(()=>{});}finally{submitButton.disabled=false;}});
}
const dt=value=>{const d=value?new Date(value):new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
function orderForm(defaultType='Correctiva'){form('Crear orden de trabajo',[assetField(),{name:'title',label:'Trabajo requerido',required:true,wide:true},{name:'type',label:'Tipo',type:'select',options:['Correctiva','Preventiva','Inspección','Mejora'],value:defaultType,required:true},{name:'impact',label:'Impacto observado',type:'select',options:['Sin detención','Producción reducida','Producción detenida','Seguridad']},{name:'urgency',label:'Urgencia',type:'select',options:['Normal','Hoy','Inmediata','Planificada']},{name:'priority',label:'Prioridad',type:'select',options:[{value:'auto',label:'Automática según impacto'},'Media','Alta','Baja'],value:'auto'},{name:'priorityReason',label:'Motivo si reemplazas la prioridad sugerida'},{name:'dueAt',label:'Vencimiento',type:'datetime-local',required:true,value:dt(Date.now()+86400000)},{name:'plannedAt',label:'Inicio previsto',type:'datetime-local',value:dt()},{name:'estimatedHours',label:'Horas estimadas',type:'number',value:1,min:0,step:'0.25',required:true},{name:'templateId',label:'Procedimiento',type:'select',options:options(state.templates)},{name:'clearanceRequired',label:'Requiere autorización de trabajo',type:'checkbox'},{name:'hazard',label:'Riesgos / condiciones previas',type:'textarea',wide:true}],p=>act('order.create',p));}
function requestForm(){form('Reportar falla',[assetField(),{name:'condition',label:'Condición observada',type:'select',options:['Operando con anomalía','Equipo detenido','Riesgo que requiere atención'],required:true},{name:'description',label:'¿Qué ocurre?',type:'textarea',wide:true,required:true}],p=>act('request.create',p),'Enviar aviso','El usuario y la fecha se registran automáticamente.');}
function assetForm(a){const fields=[{name:'code',label:'Código único',required:true,value:a?.code},{name:'name',label:'Nombre',required:true,value:a?.name},{name:'location',label:'Ubicación',required:true,value:a?.location},{name:'equipmentType',label:'Tipo de equipo',required:true,value:a?.equipmentType||'Otro',help:'Por ejemplo: bomba, motor, transportador o compresor.'},{name:'parentId',label:'Equipo / línea superior',type:'select',options:options(state.assets.filter(x=>x.id!==a?.id)),value:a?.parentId},{name:'criticality',label:'Criticidad',type:'select',options:['Media','Alta','Baja'],value:a?.criticality},{name:'brand',label:'Marca',value:a?.brand},{name:'model',label:'Modelo',value:a?.model},{name:'serial',label:'Número de serie',value:a?.serial},{name:'operatingSchedule',label:'Calendario de operación',value:a?.operatingSchedule},{name:'unit',label:'Unidad de medidor',value:a?.unit||'h'}];form(a?'Editar activo':'Registrar activo',a?fields.filter(f=>!['code','unit'].includes(f.name)):fields,p=>act(a?'asset.update':'asset.create',{...p,...(a?{id:a.id}:{})},a));}
function triage(id){const r=state.requests.find(x=>x.id===id);form('Revisar '+r.code,[{name:'decision',label:'Decisión',type:'select',required:true,options:[{value:'accept',label:'Aceptar y crear orden'},{value:'link',label:'Vincular a orden existente'},{value:'reject',label:'Rechazar con motivo'}]},{name:'orderId',label:'Orden existente del mismo activo',type:'select',options:options(state.orders.filter(o=>o.assetId===r.assetId&&!closed(o)).map(o=>({...o,name:o.code+' · '+o.title})))},{name:'title',label:'Título de nueva orden',value:r.description},{name:'priority',label:'Prioridad',type:'select',options:[{value:'auto',label:'Automática según impacto'},'Media','Alta','Baja'],value:'auto'},{name:'reason',label:'Motivo / observaciones',type:'textarea',wide:true}],p=>act('request.triage',{...p,id},r),'Confirmar',r.description);}
function orderDetail(id,tab='overview'){
 selectedOrder=id;detailTab=tab;const o=state.orders.find(x=>x.id===id);if(!o){toast('Orden no disponible para este usuario');return;}const asset=state.assets.find(a=>a.id===o.assetId);const writable=can('supervisor')||user.role==='technician'&&o.technicianIds.includes(user.id);const tabs=[['overview','Resumen'],['tasks','Tareas'],['work','Intervenciones'],['parts','Repuestos'],['handover','Turnos'],['files','Evidencias'],['history','Historial']];
 let content='';
 if(tab==='overview')content=`<div class="row">${badge(o.status)}<span class="${o.priority==='Alta'?'priority-high':'muted'}">Prioridad ${esc(o.priority)}</span>${due(o)?badge('Vencida'):''}</div><div class="detail-grid">${[['Activo',asset?`${asset.code} · ${asset.name}`:'—'],['Ubicación',asset?.location],['Tipo / origen',`${o.type} · ${o.source}`],['Responsables',o.technicianIds.map(id=>name('users',id)).join(', ')||'Sin asignar'],['Inicio previsto',fmt(o.plannedAt)],['Vencimiento',fmt(o.dueAt)]].map(([label,value])=>`<div><span class="small muted">${esc(label)}</span><div class="detail-value">${esc(value)}</div></div>`).join('')}</div><hr class="divider"><div class="row">${can('supervisor')&&!closed(o)?button('Asignar / reasignar','assign',id)+button('Planificar / priorizar','edit-order',id):''}${writable?button('Cambiar estado','transition',id):''}${can('supervisor')&&!closed(o)?button('Autorizar trabajo','clearance',id):''}${writable&&o.status==='En prueba'?button('Registrar prueba','test',id):''}${can('supervisor')?button('Agregar costo','expense',id):''}</div>${o.clearanceRequired?`<div class="banner ${o.clearance?'':'warn'}">Autorización requerida · ${o.clearance?`Referencia ${esc(o.clearance.reference)} · ${esc(o.clearance.note)}`:'Pendiente antes de iniciar'}</div>`:''}${o.acceptance?`<p class="sub">Prueba: ${badge(o.acceptance.passed?'Pass':'Fail')} ${esc(o.acceptance.note)} · ${fmt(o.acceptance.at)}</p>`:''}<p class="caption">Finalizar la orden conserva el historial. El retorno del equipo a servicio se registra por separado en la ficha del activo.</p>`;
 if(tab==='tasks')content=`<p class="sub">${esc(name('templates',o.templateId))} ${o.templateVersion?'· versión '+o.templateVersion:''}</p><hr class="divider">${o.tasks.map(t=>{const c=o.checks.find(c=>c.taskId===t.id);return `<section class="panel"><div class="row between"><h3>${esc(t.label)}</h3>${c?badge(c.result):badge('Pendiente')}</div>${t.type==='reading'?`<p class="sub">${esc(t.unit)} · Rango ${t.min??'—'} a ${t.max??'—'}</p>`:''}${c?`<p class="sub">${esc(c.value??'')} ${esc(c.note)} · ${fmt(c.at)}</p>`:''}${writable&&!closed(o)?button('Registrar resultado','check',t.id):''}${c?.followUpId?`<p class="sub">Seguimiento: ${esc(name('orders',c.followUpId,'code'))}</p>`:''}</section>`;}).join('<br>')||empty('Esta orden no tiene lista de tareas','Selecciona un procedimiento al crear la orden.')}`;
 if(tab==='work')content=`${writable&&!closed(o)?button('Registrar intervención','intervention',id,true,'plus'):''}<hr class="divider">${state.interventions.filter(i=>i.orderId===id).map(i=>`<article class="timeline-item"><h3>${esc(i.diagnosis)}</h3><p>${esc(i.activity)}</p><p class="sub">${esc(i.failureCode)} · ${esc(i.cause||'Causa sin determinar')} ${i.causeConfirmed?'(confirmada)':'(probable)'}</p><p class="small muted">${esc(name('users',i.authorId))} · ${n(i.hours)} h · ${fmt(i.endedAt)}</p>${can('supervisor')?button('Corregir horas','correct-time',i.id):''}</article>`).join('')||empty('Sin intervenciones registradas')}`;
 if(tab==='parts')content=table(['Repuesto','Movimiento','Cantidad','Costo histórico'],state.movements.filter(m=>m.orderId===id).map(m=>`<tr><td>${esc(name('parts',m.partId))}</td><td>${esc(m.type)}</td><td>${n(m.quantity)}</td><td>${m.costSnapshot===undefined?'Restringido':money(m.quantity*m.costSnapshot,m.currency)}</td></tr>`))+`<p class="caption">Las entregas y devoluciones se registran desde Bodega y repuestos.</p>`;
 if(tab==='handover')content=`${writable&&!closed(o)?button('Entregar turno','handover',id,true):''}<hr class="divider">${[...o.handover].reverse().map(h=>`<article class="panel"><h3>${esc(name('users',h.by))} → ${esc(name('users',h.nextUserId))}</h3><p class="sub">${fmt(h.at)}</p><p class="sub">Estado: ${esc(h.condition)}</p><p class="sub">Pendiente: ${esc(h.pending)}</p><p class="sub">Precauciones: ${esc(h.precautions||'Sin observaciones')}</p>${h.ackAt?badge('Recibida'):h.nextUserId===user.id?button('Confirmar recepción','handover-ack',h.id):badge('Pendiente de recepción')}</article>`).join('<br>')||empty('Sin entregas de turno')}`;
 if(tab==='files')content=`${writable&&!closed(o)?button('Adjuntar foto / documento','attach',id,true):''}<hr class="divider">${table(['Archivo','Usuario','Fecha',''],state.documents.filter(d=>d.orderId===id).map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(name('users',d.authorId))}</td><td>${fmt(d.occurredAt)}</td><td>${documentActions(d)}</td></tr>`))}`;
 if(tab==='history')content=`<div id="order-audit" class="small muted">Cargando eventos…</div>`;
 openDialog(`${o.code} · ${o.title}`,`<div class="tabs">${tabs.map(([key,label])=>`<button type="button" class="tab ${key===tab?'active':''}" data-do="order-tab" data-id="${key}">${label}</button>`).join('')}</div>${content}`,asset?.name,true);
 if(tab==='history')loadOrderAudit(id);
}
async function loadOrderAudit(id){const el=modal.querySelector('#order-audit');try{if(!can('supervisor','manager')){el.textContent='El historial de intervenciones y entregas de turno está disponible en las pestañas correspondientes. La auditoría administrativa requiere permiso.';return;}const events=online&&!manualOffline?await api('/api/audit?site='+site):(state.audit||[]);el.innerHTML=`<div class="timeline">${events.filter(e=>e.subject_id===id||e.details?.payload?.orderId===id).map(e=>`<article class="timeline-item"><h3>${esc(e.operation)}</h3><p>${esc(name('users',e.actor_id))} · ${fmt(e.occurred_at)}</p><p class="small muted">Recepción: ${fmt(e.received_at)}</p></article>`).join('')||'Sin eventos registrados'}</div>`;}catch(e){el.textContent=e.message;}}
function documentActions(doc){
 const cached=doc.base64||journal?.files[doc.id]?.base64;
 return `${cached||online&&!manualOffline?button('Descargar','download-document',doc.id):'<span class="caption">Archivo no preparado para uso sin conexión</span>'}${cached?badge('Disponible sin conexión'):online&&!manualOffline?button('Guardar sin conexión','cache-document',doc.id):''}`;
}
async function fetchDocument(id){
 const doc=state.documents.find(d=>d.id===id);assertLocal(doc,'Archivo no disponible para este usuario');
 if(doc.base64)return doc;if(journal?.files[id])return journal.files[id];
 assertLocal(online&&!manualOffline,'Este archivo aún no está guardado en el dispositivo.');
 let response;try{response=await fetch('/api/document?site='+encodeURIComponent(site)+'&id='+encodeURIComponent(id),{headers:{'X-Workspace-User':user.id},signal:AbortSignal.timeout(12000)});}catch{throw Error('No se pudo descargar. Reintenta al recuperar la conexión.');}
 if(!response.ok)throw Error('El servidor no permitió descargar este archivo.');const blob=await response.blob();assertLocal(blob.size<=5*1024*1024,'El archivo supera 5 MB');return {...doc,base64:await fileBase64(blob)};
}
function assetDetail(id){const a=state.assets.find(x=>x.id===id);if(!a)return;const history=state.orders.filter(o=>o.assetId===id),stops=state.downtime.filter(d=>d.assetId===id),open=stops.find(d=>!d.endedAt);openDialog(`${a.code} · ${a.name}`,`<div class="row between">${badge(a.status)}${online&&!manualOffline?`<a href="/api/qr?site=${encodeURIComponent(site)}&asset=${encodeURIComponent(id)}" target="_blank" rel="noopener">Abrir etiqueta QR</a>`:'<span class="caption">La etiqueta QR requiere conexión</span>'}</div><div class="detail-grid">${[['Tipo de equipo',a.equipmentType||'Otro'],['Ubicación',a.location],['Equipo superior',name('assets',a.parentId)],['Criticidad',a.criticality],['Marca / modelo',`${a.brand||'—'} / ${a.model||'—'}`],['Serie',a.serial||'—'],['Medidor',`${n(a.meter)} ${a.unit||'h'}`]].map(([k,v])=>`<div><span class="small muted">${k}</span><p class="detail-value">${esc(v)}</p></div>`).join('')}</div><div class="row">${can('supervisor')?button('Editar ficha','edit-asset',id):''}${can('technician','supervisor')&&a.status!=='Retirado'?button('Registrar lectura','reading',id):''}${can('operator','technician','supervisor')&&a.status!=='Retirado'&&!open?button('Registrar detención','stop',id):''}${can('supervisor')&&open?button('Retorno a servicio','return-service',open.id):''}${can('supervisor')&&a.status!=='Retirado'?button('Retirar activo','retire',id):''}</div><hr class="divider"><h3 class="panel-heading">Documentación del activo</h3>${can('technician','supervisor','warehouse')?button('Adjuntar documento','attach-asset',id):''}${table(['Archivo','Fecha',''],state.documents.filter(d=>d.assetId===id).map(d=>`<tr><td>${esc(d.name)}</td><td>${fmt(d.occurredAt)}</td><td>${documentActions(d)}</td></tr>`))}<hr class="divider"><h3 class="panel-heading">Historial de órdenes</h3>${table(['Orden','Trabajo','Estado'],history.map(o=>`<tr><td>${link(o.code,'order',o.id)}</td><td>${esc(o.title)}</td><td>${badge(o.status)}</td></tr>`))}<hr class="divider"><h3 class="panel-heading">Detenciones</h3>${table(['Inicio','Retorno','Motivo','Tipo'],stops.map(d=>`<tr><td>${fmt(d.startedAt)}</td><td>${fmt(d.endedAt)}</td><td>${esc(d.reason)}</td><td>${d.planned?'Planificada':'No planificada'}</td></tr>`))}<hr class="divider"><h3 class="panel-heading">Lecturas</h3>${table(['Fecha','Lectura','Acumulado','Usuario'],state.readings.filter(r=>r.assetId===id).map(r=>`<tr><td>${fmt(r.occurredAt)}</td><td>${n(r.value)} ${esc(r.unit)}</td><td>${n(r.effectiveValue)}</td><td>${esc(name('users',r.by))}</td></tr>`))}`,a.location,true);}

