 'cache-document':async id=>{assertLocal(journal&&vaultUnlocked(),'Desbloquea tu copia de trabajo primero.');const doc=await fetchDocument(id),previous=journal.files[id];journal.files[id]=doc;try{await journal.persist();}catch(error){if(previous)journal.files[id]=previous;else delete journal.files[id];throw error;}if(doc.orderId)orderDetail(doc.orderId,'files');else assetDetail(doc.assetId);toast('Archivo protegido y disponible sin conexión');},
