 'import-pending':()=>fileForm('Recuperar pendientes cifrados',async file=>{assertLocal(vaultUnlocked(),'Primero desbloquea la copia local');const exported=JSON.parse(await file.text());assertLocal(exported.format==='fast-up-encrypted-v1'&&exported.iterations===310000&&exported.salt?.length===16&&exported.iv?.length===12,'Formato de recuperación inválido');const passphrase=prompt('Frase del archivo cifrado:');assertLocal(passphrase,'La frase es obligatoria');const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']),key=await crypto.subtle.deriveKey({name:'PBKDF2',salt:new Uint8Array(exported.salt),iterations:310000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['decrypt']);const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(exported.iv)},key,new Uint8Array(exported.data));const recovered=JSON.parse(new TextDecoder().decode(bytes));assertLocal(recovered.userId===user.id&&user.siteIds.includes(recovered.siteId)&&Array.isArray(recovered.queue),'El archivo pertenece a otro usuario o planta');assertLocal(recovered.queue.every(q=>q.operationId&&q.payload&&user.siteIds.includes(q.siteId)),'Cola inválida');const existing=new Set(journal.entries.map(q=>q.operationId)),before=structuredClone(journal.entries);journal.entries.push(...recovered.queue.filter(q=>!existing.has(q.operationId)));try{await journal.persist();}catch(error){journal.entries=before;throw error;}journal.rebuild();},'.json'),
