function userForm(u){form(u?'Editar usuario':'Nuevo usuario',[{name:'name',label:'Nombre',required:true,value:u?.name},{name:'email',label:'Correo',type:'email',required:true,value:u?.email},{name:'role',label:'Rol',type:'select',options:Object.entries(labels).map(([value,label])=>({value,label})),value:u?.role,required:true},{name:'password',label:u?'Nueva contraseña (opcional)':'Contraseña (mínimo 14 caracteres)',type:'password',required:!u,minlength:14},{name:'hourlyRate',label:'Tarifa de costeo por hora',type:'number',min:0,value:u?.hourlyRate||0},{name:'specialty',label:'Especialidad',value:u?.specialty},{name:'shift',label:'Turno',value:u?.shift||'Día'},{name:'siteIds',label:'Plantas (selección múltiple)',type:'select',multiple:true,required:true,options:options(state.sites),value:u?.siteIds||[site]},{name:'active',label:'Cuenta activa',type:'checkbox',value:u?.active??true},{name:'available',label:'Disponible para asignación',type:'checkbox',value:u?.available??true}],async p=>{await api('/api/users',{method:'POST',body:JSON.stringify({...p,...(u?{id:u.id}:{})})});await refresh();});}
function fileForm(title,callback,accept){openDialog(title,`<form id="file-form"><label>Archivo (máximo 5 MB)<input type="file" accept="${accept}" required></label><div class="form-error" role="alert"></div><div class="form-actions"><button class="primary" type="submit">Continuar</button></div></form>`);modal.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const el=e.currentTarget,submit=el.querySelector('button');submit.disabled=true;try{const file=el.querySelector('input').files[0];assertLocal(file&&file.size<=5*1024*1024,'Archivo demasiado grande');await callback(file);modal.close();shell();toast('Archivo procesado');}catch(error){el.querySelector('.form-error').textContent=error.message;}finally{submit.disabled=false;}});}
const fileBase64=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(r.error);r.readAsDataURL(file);});
function importForm(){fileForm('Cargar Excel / CSV',async file=>{let rows;if(file.name.toLowerCase().endsWith('.csv'))rows=parseCSV(await file.text());else rows=(await api('/api/import-file',{method:'POST',body:JSON.stringify({base64:await fileBase64(file)})})).rows;const kind=prompt('Destino: assets (activos), parts (repuestos) o history (intervenciones históricas)','assets');assertLocal(['assets','parts','history'].includes(kind),'Destino inválido');await act(kind==='history'?'history.preview':'import.preview',{rows,kind,source:file.name});},'.xlsx,.csv');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;const delimiter=text.split('\n')[0].includes(';')?';':',';for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(Boolean))rows.push(row);assertLocal(!quoted,'CSV con comillas sin cerrar');const keys=(rows.shift()||[]).map(k=>k.replace(/^\ufeff/,'').trim());return rows.map(values=>Object.fromEntries(keys.map((key,i)=>[key,values[i]||''])));}
function importDetail(id){const i=state.imports.find(x=>x.id===id);openDialog('Importación · '+i.source,`${badge(i.status)}<p class="sub">${i.rows.length} filas · ${i.rows.filter(r=>r.errors.length).length} con errores. Las filas inválidas se omiten explícitamente al confirmar.</p><hr class="divider">${table(['Fila','Código','Nombre','Validación'],i.rows.slice(0,100).map(r=>`<tr><td>${r.line}</td><td>${esc(r.data.code)}</td><td>${esc(r.data.name)}</td><td>${r.errors.length?esc(r.errors.join('; ')):badge('Válida')}</td></tr>`))}<div class="form-actions">${i.status==='Validado'?button('Importar válidas / omitir inválidas','commit-import',id,true):i.status==='Importado'?button('Revertir lote sin dependencias','reverse-import',id):''}</div>`,`${i.kind} · vista de primeras 100 filas`,true);}
handlers['commit-import']=async id=>{const i=state.imports.find(x=>x.id===id);await act(i.kind==='history'?'history.commit':'import.commit',{id,skipLines:i.rows.filter(r=>r.errors.length).map(r=>r.line)},i);modal.close();shell();toast('Lote importado');};
handlers['reverse-import']=id=>{const i=state.imports.find(x=>x.id===id);form('Revertir importación',[{name:'reason',label:'Motivo',required:true}],p=>act(i.kind==='history'?'history.reverse':'import.reverse',{...p,id},i));};
handlers['export-report']=()=>{
 assertLocal(lastReport,'Primero genera un reporte');const r=lastReport;
 const rows=[['Fast Up','Indicadores de mantenimiento'],['Planta',currentSite()?.name],['Desde incluido (UTC)',r.from],['Hasta excluido (UTC)',r.to],['Activo',r.filters?.assetId?name('assets',r.filters.assetId):'Todos'],['Tipo',r.filters?.workType||'Todos'],[],['Indicador','Valor','Unidad','Moneda'],['Órdenes abiertas actuales',r.open,'órdenes',''],['Órdenes vencidas actuales',r.overdue,'órdenes',''],['Órdenes finalizadas',r.closed,'órdenes',''],['Horas de trabajo',r.laborHours,'h',''],['Mano de obra con tarifa conocida',r.laborCost,'costo',currentSite()?.currency],['Intervenciones sin tarifa',r.unknownLaborCostEntries,'registros',''],['Preventivos en plazo',r.preventiveOnTime,'órdenes',''],['Preventivos con vencimiento en período',r.preventiveDue,'órdenes',''],...Object.entries(r.partsByCurrency).map(([currency,v])=>['Repuestos',v,'costo',currency]),...Object.entries(r.expensesByCurrency).map(([currency,v])=>['Servicios / otros',v,'costo',currency]),[],['Código','Equipo','Detención planificada h','Detención no planificada h','Fallas iniciadas','Horas operativas verificadas','MTBF h','Restauración media h'],...r.assets.map(a=>[a.code,a.name,a.plannedHours,a.unplannedHours,a.failures,a.runtimeHours??'Datos incompletos',a.mtbfHours??'Datos insuficientes',a.meanRestorationHours??'Sin retornos']),[],...Object.entries(r.definitions).map(([key,value])=>['Definición: '+key,value])];
 download('fast-up-indicadores.csv','\ufeff'+rows.map(row=>row.map(csv).join(';')).join('\r\n'),'text/csv');
};
const csv=value=>'"'+String(value??'').replace(/^[\t\r\n ]*[=+@-]/,"'"+'$&').replace(/"/g,'""')+'"';
function download(filename,text,mime){const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function navigate(id){page=id;query='';statusFilter='';typeFilter='';profileOpen=false;document.body.classList.remove('navigation-open');shell();}
async function click(event){const target=event.target.closest('[data-do],[data-nav]');if(!target)return;try{if(target.dataset.nav){event.preventDefault();return navigate(target.dataset.nav)};if((!online||manualOffline)&&requiresServer.has(target.dataset.do)){toast('Esta operación estará disponible al conectar con el servidor.');return;}activeContext=target.dataset.id||'';const handler=handlers[target.dataset.do];if(handler)await handler(target.dataset.id);}catch(error){toast(error.message);}}
